	tkey.tunnel_ttl = 64;
	tkey.remote_ipv4 = 0x0a020166; /* 10.2.1.102 */
	bpf_skb_set_tunnel_key(skb, &tkey, sizeof(tkey), 0);
	return bpf_redirect(*ifindex, 0);
}

